  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--accent);
  color: var(--accent);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  padding: 8px 0;
}

.btn-ghost:hover {
  color: var(--accent-hover);
}

/* ========== PRODUCT CARDS ========== */
.product-cards {
  padding: 40px 24px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
  opacity: 0;
  transition: opacity var(--transition);
}

.product-card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0, 229, 160, 0.08);
}

.product-card:hover::before {
  opacity: 1;
}

.product-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.product-card-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
  fill: none;
}

.product-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
  flex: 1;
  margin-bottom: 20px;
}

.product-card .btn-ghost {
  align-self: flex-start;
  font-weight: 600;
}

/* ========== CLI SETUP ========== */
.cli-setup {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.cli-setup .section-header {
  max-width: 600px;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section-header p {
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.7;
}

.cli-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

/* Accordion */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.accordion-item {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition);
}

.accordion-item.active {
  border-color: var(--accent);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: var(--bg-secondary);
  border: none;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font-sans);
  cursor: pointer;
  transition: all var(--transition);
}

.accordion-trigger:hover {
  background: var(--bg-tertiary);
}

.accordion-trigger .chevron {
  width: 20px;
  height: 20px;
  stroke: var(--text-muted);
  transition: transform var(--transition);
}

.accordion-item.active .accordion-trigger .chevron {
  transform: rotate(180deg);
  stroke: var(--accent);
}

.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-item.active .accordion-panel {
  max-height: 500px;
}

.accordion-panel-inner {
  padding: 20px;
  background: var(--bg-primary);
}

.accordion-panel ol {
  list-style: none;
  counter-reset: steps;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.accordion-panel ol li {
  counter-increment: steps;
  display: flex;
  gap: 12px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.accordion-panel ol li::before {
  content: counter(steps);
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-dim);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 700;
}

/* Code Block */
.code-block {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-tertiary);
}

.code-tab {
  padding: 10px 20px;
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.85rem;
  font-weight: 500;
  font-family: var(--font-sans);
  cursor: pointer;
  position: relative;
  transition: color var(--transition);
}

.code-tab:hover {
  color: var(--text-secondary);
}

.code-tab.active {
  color: var(--accent);
}

.code-tab.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
}

.code-content {
  padding: 20px;
}

.code-content pre {
  font-size: 0.88rem;
  line-height: 1.7;
  color: var(--text-primary);
  overflow-x: auto;
}

.code-content .token-comment {
  color: var(--text-muted);
}

.code-content .token-string {
  color: #a5d6ff;
}

.code-content .token-cmd {
  color: var(--accent);
}

.code-line {
  display: block;
}

.code-line .prompt {
  color: var(--accent);
  user-select: none;
}

/* ========== LAUNCH CTA ========== */
.launch-cta {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.launch-card:hover {
  border-color: var(--border-subtle);
  transform: translateY(-2px);
}

.launch-card h3 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 20px;
}

/* ========== COMMUNITY ========== */
.community {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.community h2 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.community-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.community-card h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.community-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
  flex: 1;
}

.community-card .arrow {
  color: var(--accent);
  font-size: 1.2rem;
  margin-top: 12px;
  transition: transform var(--transition);
}

.community-card:hover .arrow {
  transform: translateX(4px);
}

/* ========== FOOTER ========== */
.site-footer {
  border-top: 1px solid var(--border-color);
  padding: 60px 24px 40px;
  background: var(--bg-secondary);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}

.footer-col h5 {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 16px;
