.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.8rem;
}

/* ========== SIDEBAR LAYOUT (Apps/Agents) ========== */
.docs-layout {
  display: flex;
  min-height: calc(100vh - var(--header-height));
}

.docs-sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-color);
  background: var(--bg-secondary);
  position: sticky;
  top: var(--header-height);
  height: calc(100vh - var(--header-height));
  overflow-y: auto;
  transition: width var(--transition), opacity var(--transition);
}

.docs-sidebar.collapsed {
  width: 0;
  opacity: 0;
  overflow: hidden;
  border-right: none;
}

.sidebar-inner {
  padding: 24px 16px;
}

.sidebar-section {
  margin-bottom: 24px;
}

.sidebar-section h4 {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 10px;
  padding: 0 12px;
}

.sidebar-nav {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sidebar-nav a {
  display: block;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.88rem;
  color: var(--text-secondary);
  transition: all var(--transition);
}

.sidebar-nav a:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.sidebar-nav a.active {
  color: var(--accent);
  background: var(--accent-dim);
}

.sidebar-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 6px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  cursor: pointer;
  position: fixed;
  top: calc(var(--header-height) + 16px);
  z-index: 50;
  transition: all var(--transition);
  left: calc(var(--sidebar-width) + 8px);
}

.sidebar-toggle.collapsed {
  left: 8px;
}

.sidebar-toggle:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.sidebar-toggle svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  transition: transform var(--transition);
}

.sidebar-toggle.collapsed svg {
  transform: rotate(180deg);
}

.docs-main {
  flex: 1;
  min-width: 0;
  padding: 48px;
  max-width: 900px;
}

/* ========== CONTENT SECTIONS (Interior Pages) ========== */
.section {
  margin-bottom: 64px;
}

.section h2 {
  font-size: 1.8rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section > p {
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.7;
  margin-bottom: 32px;
  max-width: 700px;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.feature-grid.cols-3 {
  grid-template-columns: repeat(3, 1fr);
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.feature-card h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 0.88rem;
  line-height: 1.6;
}

/* ========== BEST PRACTICES ========== */
.best-practices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.bp-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
}

.bp-card:hover {
  border-color: var(--accent);
}

.bp-card h4 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.bp-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
}

/* ========== PROTOCOL ACTORS / DIAGRAMS ========== */
.actor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 32px;
}

.actor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  text-align: center;
  transition: all var(--transition);
}

.actor-card:hover {
  border-color: var(--accent);
}

.actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 14px;
}

.actor-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
  fill: none;
}

.actor-card h4 {
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 6px;
}

.actor-card p {
  color: var(--text-secondary);
  font-size: 0.82rem;
  line-height: 1.5;
}

/* ========== HOW IT WORKS STEPS ========== */
.steps {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.step {
  display: flex;
  gap: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: border-color var(--transition);
}

.step:hover {
  border-color: var(--accent);
}

.step-number {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--accent-dim);
  color: var(--accent);
  font-weight: 700;
  font-size: 0.9rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.step h4 {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.step p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* ========== COMING SOON BADGE ========== */
.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-soon {
  background: rgba(57, 213, 255, 0.12);
  color: var(--accent-cyan);
}

/* ========== SUPPORT PAGE ========== */
.support-hero {
  text-align: center;
  padding: 80px 24px 48px;
  max-width: 700px;
  margin: 0 auto;
}

.support-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.support-hero p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  margin-bottom: 28px;
}

.support-categories {
  padding: 40px 24px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.support-categories h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
}

.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: all var(--transition);
}

.support-card:hover {
  border-color: var(--accent);
}

.support-card h4 {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.support-card p {
  color: var(--text-secondary);
  font-size: 0.88rem;
  line-height: 1.5;
}

.general-queries {
  padding: 40px 24px 80px;
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.general-queries h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.general-queries p {
  color: var(--text-secondary);
  font-size: 1rem;
  margin-bottom: 24px;
}

/* ========== PAGE-LEVEL HERO (Interior) ========== */
.page-hero {
  padding: 48px 0 40px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 48px;
}

.page-hero h1 {
  font-size: 2.2rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: 12px;
}

.page-hero p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.7;
  max-width: 650px;
}

/* ========== THEME CARDS ========== */
.theme-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 48px;
}

.theme-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: all var(--transition);
}

.theme-card:hover {
  border-color: var(--accent);
}

.theme-card h4 {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.theme-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .cards-grid {
    grid-template-columns: 1fr 1fr;
  }

  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cli-content {
    grid-template-columns: 1fr;
  }

  .feature-grid.cols-3,
  .best-practices-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .actor-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .docs-sidebar {
    width: 0;
    opacity: 0;
    overflow: hidden;
    border-right: none;
  }

  .sidebar-toggle {
    left: 8px;
  }

  .sidebar-toggle svg {
    transform: rotate(180deg);
  }

  .docs-sidebar.mobile-open {
    width: var(--sidebar-width);
    opacity: 1;
    overflow-y: auto;
    border-right: 1px solid var(--border-color);
    position: fixed;
    left: 0;
    top: var(--header-height);
    z-index: 90;
  }
}

@media (max-width: 768px) {
  .hero h1 {
    font-size: 2rem;
  }

  .hero p {
    font-size: 1rem;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .cards-grid {
    grid-template-columns: 1fr;
  }

  .launch-grid {
    grid-template-columns: 1fr;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 12px;
    text-align: center;
  }

  .nav-links {
    display: none;
  }

  .nav-search {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    padding: 16px;
    z-index: 90;
  }

  .section h2 {
    font-size: 1.4rem;
  }

  .feature-grid,
  .feature-grid.cols-3,
  .best-practices-grid {
    grid-template-columns: 1fr;
  }

  .actor-grid {
    grid-template-columns: 1fr 1fr;
  }

  .support-grid {
    grid-template-columns: 1fr;
  }

  .docs-main {
    padding: 24px;
  }

  .theme-options {
    grid-template-columns: 1fr;
  }

  .support-hero h1 {
    font-size: 1.8rem;
  }
}

@media (max-width: 480px) {
  .header-inner {
    padding: 0 16px;
  }

  .hero {
    padding: 48px 16px 40px;
  }

  .hero h1 {
    font-size: 1.6rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .actor-grid {
    grid-template-columns: 1fr;
  }
}
