/* CommerceForge Dev Docs — Global Styles */
:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2129;
  --bg-card: #161b22;
  --bg-card-hover: #1c2129;
  --border-color: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00e5a0;
  --accent-hover: #00c98b;
  --accent-dim: rgba(0, 229, 160, 0.12);
  --accent-blue: #58a6ff;
  --accent-cyan: #39d5ff;
  --code-bg: #0d1117;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Consolas, monospace;
  --radius: 8px;
  --radius-lg: 12px;
  --sidebar-width: 260px;
  --header-height: 60px;
  --max-width: 1200px;
  --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--accent-hover);
}

code, pre {
  font-family: var(--font-mono);
}

img {
  max-width: 100%;
  display: block;
}

/* ========== HEADER / NAV ========== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  height: var(--header-height);
}

.header-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
  white-space: nowrap;
}

.logo svg {
  width: 28px;
  height: 28px;
  fill: var(--accent);
}

.logo span {
  color: var(--accent);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.nav-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 6px 12px;
  color: var(--text-muted);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color var(--transition);
}

.nav-search:hover {
  border-color: var(--text-muted);
}

.nav-search svg {
  width: 16px;
  height: 16px;
  stroke: var(--text-muted);
}

.nav-search kbd {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  padding: 1px 6px;
  font-size: 0.75rem;
  font-family: var(--font-sans);
}

.btn-login {
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-primary);
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  cursor: pointer;
  transition: all var(--transition);
}

.btn-login:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-muted);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 8px;
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
  stroke: currentColor;
}

/* ========== HERO ========== */
.hero {
  padding: 80px 24px 60px;
  text-align: center;
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero h1 {
  font-size: 3rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.15rem;
  color: var(--text-secondary);
  max-width: 720px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ========== BUTTONS ========== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all var(--transition);
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: #0d1117;
}

.btn-primary:hover {
  background: var(--accent-hover);
  color: #0d1117;
  transform: translateY(-1px);
  box-shadow: 0 4px 20px rgba(0, 229, 160, 0.25);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--accent);
  color: var(--accent);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  padding: 8px 0;
}

.btn-ghost:hover {
  color: var(--accent-hover);
}

/* ========== PRODUCT CARDS ========== */
.product-cards {
  padding: 40px 24px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
  opacity: 0;
  transition: opacity var(--transition);
}

.product-card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0, 229, 160, 0.08);
}

.product-card:hover::before {
  opacity: 1;
}

.product-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.product-card-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
  fill: none;
}

.product-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
  flex: 1;
  margin-bottom: 20px;
}

.product-card .btn-ghost {
  align-self: flex-start;
  font-weight: 600;
}

/* ========== CLI SETUP ========== */
.cli-setup {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.cli-setup .section-header {
  max-width: 600px;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section-header p {
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.7;
}

.cli-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

/* Accordion */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.accordion-item {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition);
}

.accordion-item.active {
  border-color: var(--accent);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: var(--bg-secondary);
  border: none;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font-sans);
  cursor: pointer;
  transition: all var(--transition);
}

.accordion-trigger:hover {
  background: var(--bg-tertiary);
}

.accordion-trigger .chevron {
  width: 20px;
  height: 20px;
  stroke: var(--text-muted);
  transition: transform var(--transition);
}

.accordion-item.active .accordion-trigger .chevron {
  transform: rotate(180deg);
  stroke: var(--accent);
}

.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-item.active .accordion-panel {
  max-height: 500px;
}

.accordion-panel-inner {
  padding: 20px;
  background: var(--bg-primary);
}

.accordion-panel ol {
  list-style: none;
  counter-reset: steps;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.accordion-panel ol li {
  counter-increment: steps;
  display: flex;
  gap: 12px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.accordion-panel ol li::before {
  content: counter(steps);
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-dim);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 700;
}

/* Code Block */
.code-block {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-tertiary);
}

.code-tab {
  padding: 10px 20px;
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.85rem;
  font-weight: 500;
  font-family: var(--font-sans);
  cursor: pointer;
  position: relative;
  transition: color var(--transition);
}

.code-tab:hover {
  color: var(--text-secondary);
}

.code-tab.active {
  color: var(--accent);
}

.code-tab.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
}

.code-content {
  padding: 20px;
}

.code-content pre {
  font-size: 0.88rem;
  line-height: 1.7;
  color: var(--text-primary);
  overflow-x: auto;
}

.code-content .token-comment {
  color: var(--text-muted);
}

.code-content .token-string {
  color: #a5d6ff;
}

.code-content .token-cmd {
  color: var(--accent);
}

.code-line {
  display: block;
}

.code-line .prompt {
  color: var(--accent);
  user-select: none;
}

/* ========== LAUNCH CTA ========== */
.launch-cta {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.launch-card:hover {
  border-color: var(--border-subtle);
  transform: translateY(-2px);
}

.launch-card h3 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 20px;
}

/* ========== COMMUNITY ========== */
.community {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.community h2 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.community-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.community-card h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.community-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
  flex: 1;
}

.community-card .arrow {
  color: var(--accent);
  font-size: 1.2rem;
  margin-top: 12px;
  transition: transform var(--transition);
}

.community-card:hover .arrow {
  transform: translateX(4px);
}

/* ========== FOOTER ========== */
.site-footer {
  border-top: 1px solid var(--border-color);
  padding: 60px 24px 40px;
  background: var(--bg-secondary);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}

.footer-col h5 {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.88rem;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.8rem;
}

/* ========== SIDEBAR LAYOUT (Apps/Agents) ========== */
.docs-layout {
  display: flex;
  min-height: calc(100vh - var(--header-height));
}

.docs-sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-color);
  background: var(--bg-secondary);
  position: sticky;
  top: var(--header-height);
  height: calc(100vh - var(--header-height));
  overflow-y: auto;
  transition: width var(--transition), opacity var(--transition);
}

.docs-sidebar.collapsed {
  width: 0;
  opacity: 0;
  overflow: hidden;
  border-right: none;
}

.sidebar-inner {
  padding: 24px 16px;
}

.sidebar-section {
  margin-bottom: 24px;
}

.sidebar-section h4 {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 10px;
  padding: 0 12px;
}

.sidebar-nav {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sidebar-nav a {
  display: block;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.88rem;
  color: var(--text-secondary);
  transition: all var(--transition);
}

.sidebar-nav a:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.sidebar-nav a.active {
  color: var(--accent);
  background: var(--accent-dim);
}

.sidebar-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 6px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  cursor: pointer;
  position: fixed;
  top: calc(var(--header-height) + 16px);
  z-index: 50;
  transition: all var(--transition);
  left: calc(var(--sidebar-width) + 8px);
}

.sidebar-toggle.collapsed {
  left: 8px;
}

.sidebar-toggle:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.sidebar-toggle svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  transition: transform var(--transition);
}

.sidebar-toggle.collapsed svg {
  transform: rotate(180deg);
}

.docs-main {
  flex: 1;
  min-width: 0;
  padding: 48px;
  max-width: 900px;
}

/* ========== CONTENT SECTIONS (Interior Pages) ========== */
.section {
  margin-bottom: 64px;
}

.section h2 {
  font-size: 1.8rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section > p {
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.7;
  margin-bottom: 32px;
  max-width: 700px;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.feature-grid.cols-3 {
  grid-template-columns: repeat(3, 1fr);
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.feature-card h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 0.88rem;
  line-height: 1.6;
}

/* ========== BEST PRACTICES ========== */
.best-practices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.bp-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
}

.bp-card:hover {
  border-color: var(--accent);
}

.bp-card h4 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.bp-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
}

/* ========== PROTOCOL ACTORS / DIAGRAMS ========== */
.actor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 32px;
}

.actor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  text-align: center;
  transition: all var(--transition);
}

.actor-card:hover {
  border-color: var(--accent);
}

.actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 14px;
}

.actor-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
  fill: none;
}

.actor-card h4 {
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 6px;
}

.actor-card p {
  color: var(--text-secondary);
  font-size: 0.82rem;
  line-height: 1.5;
}

/* ========== HOW IT WORKS STEPS ========== */
.steps {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.step {
  display: flex;
  gap: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: border-color var(--transition);
}

.step:hover {
  border-color: var(--accent);
}

.step-number {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--accent-dim);
  color: var(--accent);
  font-weight: 700;
  font-size: 0.9rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.step h4 {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.step p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* ========== COMING SOON BADGE ========== */
.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-soon {
  background: rgba(57, 213, 255, 0.12);
  color: var(--accent-cyan);
}

/* ========== SUPPORT PAGE ========== */
.support-hero {
  text-align: center;
  padding: 80px 24px 48px;
  max-width: 700px;
  margin: 0 auto;
}

.support-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.support-hero p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  margin-bottom: 28px;
}

.support-categories {
  padding: 40px 24px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.support-categories h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
}

.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: all var(--transition);
}

.support-card:hover {
  border-color: var(--accent);
}

.support-card h4 {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.support-card p {
  color: var(--text-secondary);
  font-size: 0.88rem;
  line-height: 1.5;
}

.general-queries {
  padding: 40px 24px 80px;
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.general-queries h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.general-queries p {
  color: var(--text-secondary);
  font-size: 1rem;
  margin-bottom: 24px;
}

/* ========== PAGE-LEVEL HERO (Interior) ========== */
.page-hero {
  padding: 48px 0 40px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 48px;
}

.page-hero h1 {
  font-size: 2.2rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: 12px;
}

.page-hero p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.7;
  max-width: 650px;
}

/* ========== THEME CARDS ========== */
.theme-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 48px;
}

.theme-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: all var(--transition);
}

.theme-card:hover {
  border-color: var(--accent);
}

.theme-card h4 {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.theme-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .cards-grid {
    grid-template-columns: 1fr 1fr;
  }

  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cli-content {
    grid-template-columns: 1fr;
  }

  .feature-grid.cols-3,
  .best-practices-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .actor-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .docs-sidebar {
    width: 0;
    opacity: 0;
    overflow: hidden;
    border-right: none;
  }

  .sidebar-toggle {
    left: 8px;
  }

  .sidebar-toggle svg {
    transform: rotate(180deg);
  }

  .docs-sidebar.mobile-open {
    width: var(--sidebar-width);
    opacity: 1;
    overflow-y: auto;
    border-right: 1px solid var(--border-color);
    position: fixed;
    left: 0;
    top: var(--header-height);
    z-index: 90;
  }
}

@media (max-width: 768px) {
  .hero h1 {
    font-size: 2rem;
  }

  .hero p {
    font-size: 1rem;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .cards-grid {
    grid-template-columns: 1fr;
  }

  .launch-grid {
    grid-template-columns: 1fr;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 12px;
    text-align: center;
  }

  .nav-links {
    display: none;
  }

  .nav-search {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    padding: 16px;
    z-index: 90;
  }

  .section h2 {
    font-size: 1.4rem;
  }

  .feature-grid,
  .feature-grid.cols-3,
  .best-practices-grid {
    grid-template-columns: 1fr;
  }

  .actor-grid {
    grid-template-columns: 1fr 1fr;
  }

  .support-grid {
    grid-template-columns: 1fr;
  }

  .docs-main {
    padding: 24px;
  }

  .theme-options {
    grid-template-columns: 1fr;
  }

  .support-hero h1 {
    font-size: 1.8rem;
  }
}

@media (max-width: 480px) {
  .header-inner {
    padding: 0 16px;
  }

  .hero {
    padding: 48px 16px 40px;
  }

  .hero h1 {
    font-size: 1.6rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .actor-grid {
    grid-template-columns: 1fr;
  }
}

/* CommerceForge Dev Docs — Global Styles */
:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2129;
  --bg-card: #161b22;
  --bg-card-hover: #1c2129;
  --border-color: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00e5a0;
  --accent-hover: #00c98b;
  --accent-dim: rgba(0, 229, 160, 0.12);
  --accent-blue: #58a6ff;
  --accent-cyan: #39d5ff;
  --code-bg: #0d1117;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Consolas, monospace;
  --radius: 8px;
  --radius-lg: 12px;
  --sidebar-width: 260px;
  --header-height: 60px;
  --max-width: 1200px;
  --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--accent-hover);
}

code, pre {
  font-family: var(--font-mono);
}

img {
  max-width: 100%;
  display: block;
}

/* ========== HEADER / NAV ========== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  height: var(--header-height);
}

.header-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
  white-space: nowrap;
}

.logo svg {
  width: 28px;
  height: 28px;
  fill: var(--accent);
}

.logo span {
  color: var(--accent);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  padding: 8px 14px;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.nav-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 6px 12px;
  color: var(--text-muted);
  font-size: 0.85rem;
  cursor: pointer;
  transition: border-color var(--transition);
}

.nav-search:hover {
  border-color: var(--text-muted);
}

.nav-search svg {
  width: 16px;
  height: 16px;
  stroke: var(--text-muted);
}

.nav-search kbd {
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  padding: 1px 6px;
  font-size: 0.75rem;
  font-family: var(--font-sans);
}

.btn-login {
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-primary);
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  cursor: pointer;
  transition: all var(--transition);
}

.btn-login:hover {
  background: var(--bg-tertiary);
  border-color: var(--text-muted);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 8px;
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
  stroke: currentColor;
}

/* ========== HERO ========== */
.hero {
  padding: 80px 24px 60px;
  text-align: center;
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero h1 {
  font-size: 3rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.15rem;
  color: var(--text-secondary);
  max-width: 720px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ========== BUTTONS ========== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all var(--transition);
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: #0d1117;
}

.btn-primary:hover {
  background: var(--accent-hover);
  color: #0d1117;
  transform: translateY(-1px);
  box-shadow: 0 4px 20px rgba(0, 229, 160, 0.25);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--accent);
  color: var(--accent);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--accent);
  padding: 8px 0;
}

.btn-ghost:hover {
  color: var(--accent-hover);
}

/* ========== PRODUCT CARDS ========== */
.product-cards {
  padding: 40px 24px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
  opacity: 0;
  transition: opacity var(--transition);
}

.product-card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0, 229, 160, 0.08);
}

.product-card:hover::before {
  opacity: 1;
}

.product-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.product-card-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
  fill: none;
}

.product-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
  flex: 1;
  margin-bottom: 20px;
}

.product-card .btn-ghost {
  align-self: flex-start;
  font-weight: 600;
}

/* ========== CLI SETUP ========== */
.cli-setup {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.cli-setup .section-header {
  max-width: 600px;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section-header p {
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.7;
}

.cli-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

/* Accordion */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.accordion-item {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition);
}

.accordion-item.active {
  border-color: var(--accent);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: var(--bg-secondary);
  border: none;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font-sans);
  cursor: pointer;
  transition: all var(--transition);
}

.accordion-trigger:hover {
  background: var(--bg-tertiary);
}

.accordion-trigger .chevron {
  width: 20px;
  height: 20px;
  stroke: var(--text-muted);
  transition: transform var(--transition);
}

.accordion-item.active .accordion-trigger .chevron {
  transform: rotate(180deg);
  stroke: var(--accent);
}

.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-item.active .accordion-panel {
  max-height: 500px;
}

.accordion-panel-inner {
  padding: 20px;
  background: var(--bg-primary);
}

.accordion-panel ol {
  list-style: none;
  counter-reset: steps;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.accordion-panel ol li {
  counter-increment: steps;
  display: flex;
  gap: 12px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.accordion-panel ol li::before {
  content: counter(steps);
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-dim);
  color: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 700;
}

/* Code Block */
.code-block {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-tertiary);
}

.code-tab {
  padding: 10px 20px;
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.85rem;
  font-weight: 500;
  font-family: var(--font-sans);
  cursor: pointer;
  position: relative;
  transition: color var(--transition);
}

.code-tab:hover {
  color: var(--text-secondary);
}

.code-tab.active {
  color: var(--accent);
}

.code-tab.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
}

.code-content {
  padding: 20px;
}

.code-content pre {
  font-size: 0.88rem;
  line-height: 1.7;
  color: var(--text-primary);
  overflow-x: auto;
}

.code-content .token-comment {
  color: var(--text-muted);
}

.code-content .token-string {
  color: #a5d6ff;
}

.code-content .token-cmd {
  color: var(--accent);
}

.code-line {
  display: block;
}

.code-line .prompt {
  color: var(--accent);
  user-select: none;
}

/* ========== LAUNCH CTA ========== */
.launch-cta {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.launch-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.launch-card:hover {
  border-color: var(--border-subtle);
  transform: translateY(-2px);
}

.launch-card h3 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 20px;
}

/* ========== COMMUNITY ========== */
.community {
  padding: 80px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.community h2 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.community-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.community-card h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.community-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
  flex: 1;
}

.community-card .arrow {
  color: var(--accent);
  font-size: 1.2rem;
  margin-top: 12px;
  transition: transform var(--transition);
}

.community-card:hover .arrow {
  transform: translateX(4px);
}

/* ========== FOOTER ========== */
.site-footer {
  border-top: 1px solid var(--border-color);
  padding: 60px 24px 40px;
  background: var(--bg-secondary);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}

.footer-col h5 {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.88rem;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.8rem;
}

/* ========== SIDEBAR LAYOUT (Apps/Agents) ========== */
.docs-layout {
  display: flex;
  min-height: calc(100vh - var(--header-height));
}

.docs-sidebar {
  width: var(--sidebar-width);
  flex-shrink: 0;
  border-right: 1px solid var(--border-color);
  background: var(--bg-secondary);
  position: sticky;
  top: var(--header-height);
  height: calc(100vh - var(--header-height));
  overflow-y: auto;
  transition: width var(--transition), opacity var(--transition);
}

.docs-sidebar.collapsed {
  width: 0;
  opacity: 0;
  overflow: hidden;
  border-right: none;
}

.sidebar-inner {
  padding: 24px 16px;
}

.sidebar-section {
  margin-bottom: 24px;
}

.sidebar-section h4 {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 10px;
  padding: 0 12px;
}

.sidebar-nav {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sidebar-nav a {
  display: block;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.88rem;
  color: var(--text-secondary);
  transition: all var(--transition);
}

.sidebar-nav a:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.sidebar-nav a.active {
  color: var(--accent);
  background: var(--accent-dim);
}

.sidebar-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 6px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  cursor: pointer;
  position: fixed;
  top: calc(var(--header-height) + 16px);
  z-index: 50;
  transition: all var(--transition);
  left: calc(var(--sidebar-width) + 8px);
}

.sidebar-toggle.collapsed {
  left: 8px;
}

.sidebar-toggle:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}

.sidebar-toggle svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  transition: transform var(--transition);
}

.sidebar-toggle.collapsed svg {
  transform: rotate(180deg);
}

.docs-main {
  flex: 1;
  min-width: 0;
  padding: 48px;
  max-width: 900px;
}

/* ========== CONTENT SECTIONS (Interior Pages) ========== */
.section {
  margin-bottom: 64px;
}

.section h2 {
  font-size: 1.8rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section > p {
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.7;
  margin-bottom: 32px;
  max-width: 700px;
}

.feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.feature-grid.cols-3 {
  grid-template-columns: repeat(3, 1fr);
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.feature-card h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 0.88rem;
  line-height: 1.6;
}

/* ========== BEST PRACTICES ========== */
.best-practices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.bp-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
}

.bp-card:hover {
  border-color: var(--accent);
}

.bp-card h4 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.bp-card p {
  color: var(--text-secondary);
  font-size: 0.85rem;
  line-height: 1.5;
}

/* ========== PROTOCOL ACTORS / DIAGRAMS ========== */
.actor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 32px;
}

.actor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  text-align: center;
  transition: all var(--transition);
}

.actor-card:hover {
  border-color: var(--accent);
}

.actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--accent-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 14px;
}

.actor-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--accent);
  fill: none;
}

.actor-card h4 {
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 6px;
}

.actor-card p {
  color: var(--text-secondary);
  font-size: 0.82rem;
  line-height: 1.5;
}

/* ========== HOW IT WORKS STEPS ========== */
.steps {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.step {
  display: flex;
  gap: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: border-color var(--transition);
}

.step:hover {
  border-color: var(--accent);
}

.step-number {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--accent-dim);
  color: var(--accent);
  font-weight: 700;
  font-size: 0.9rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.step h4 {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.step p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* ========== COMING SOON BADGE ========== */
.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-soon {
  background: rgba(57, 213, 255, 0.12);
  color: var(--accent-cyan);
}

/* ========== SUPPORT PAGE ========== */
.support-hero {
  text-align: center;
  padding: 80px 24px 48px;
  max-width: 700px;
  margin: 0 auto;
}

.support-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.support-hero p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  margin-bottom: 28px;
}

.support-categories {
  padding: 40px 24px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.support-categories h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
}

.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: all var(--transition);
}

.support-card:hover {
  border-color: var(--accent);
}

.support-card h4 {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.support-card p {
  color: var(--text-secondary);
  font-size: 0.88rem;
  line-height: 1.5;
}

.general-queries {
  padding: 40px 24px 80px;
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.general-queries h2 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.general-queries p {
  color: var(--text-secondary);
  font-size: 1rem;
  margin-bottom: 24px;
}

/* ========== PAGE-LEVEL HERO (Interior) ========== */
.page-hero {
  padding: 48px 0 40px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 48px;
}

.page-hero h1 {
  font-size: 2.2rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: 12px;
}

.page-hero p {
  color: var(--text-secondary);
  font-size: 1.1rem;
  line-height: 1.7;
  max-width: 650px;
}

/* ========== THEME CARDS ========== */
.theme-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 48px;
}

.theme-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: all var(--transition);
}

.theme-card:hover {
  border-color: var(--accent);
}

.theme-card h4 {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.theme-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* ========== RESPONSIVE ========== */
@media (max-width: 1024px) {
  .cards-grid {
    grid-template-columns: 1fr 1fr;
  }

  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cli-content {
    grid-template-columns: 1fr;
  }

  .feature-grid.cols-3,
  .best-practices-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .actor-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .docs-sidebar {
    width: 0;
    opacity: 0;
    overflow: hidden;
    border-right: none;
  }

  .sidebar-toggle {
    left: 8px;
  }

  .sidebar-toggle svg {
    transform: rotate(180deg);
  }

  .docs-sidebar.mobile-open {
    width: var(--sidebar-width);
    opacity: 1;
    overflow-y: auto;
    border-right: 1px solid var(--border-color);
    position: fixed;
    left: 0;
    top: var(--header-height);
    z-index: 90;
  }
}

@media (max-width: 768px) {
  .hero h1 {
    font-size: 2rem;
  }

  .hero p {
    font-size: 1rem;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .cards-grid {
    grid-template-columns: 1fr;
  }

  .launch-grid {
    grid-template-columns: 1fr;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 12px;
    text-align: center;
  }

  .nav-links {
    display: none;
  }

  .nav-search {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    padding: 16px;
    z-index: 90;
  }

  .section h2 {
    font-size: 1.4rem;
  }

  .feature-grid,
  .feature-grid.cols-3,
  .best-practices-grid {
    grid-template-columns: 1fr;
  }

  .actor-grid {
    grid-template-columns: 1fr 1fr;
  }

  .support-grid {
    grid-template-columns: 1fr;
  }

  .docs-main {
    padding: 24px;
  }

  .theme-options {
    grid-template-columns: 1fr;
  }

  .support-hero h1 {
    font-size: 1.8rem;
  }
}

@media (max-width: 480px) {
  .header-inner {
    padding: 0 16px;
  }

  .hero {
    padding: 48px 16px 40px;
  }

  .hero h1 {
    font-size: 1.6rem;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .actor-grid {
    grid-template-columns: 1fr;
  }
}

